const rows = spawnSync("sqlite3", ["-json", "app.db", "SELECT id, name FROM users LIMIT 5;"], { encoding: "utf8" }).stdout;
console.log(JSON.parse(rows || "[]"));
```

`fetch` does not throw for a 4xx or 5xx status. Check `res.ok` or
`res.status`.

